try {
  const items = $input.all();
  if (!items || items.length === 0) return [{ json: { error: 'Arquivo vazio ou ilegível.' } }];

  const results = [];
  const operators = {};
  const machines = {};
  const defectsCount = {};
  const timeline = {};
  let totalIssuesOverall = 0;

  // DYNAMIC HEADER DETECTION
  // We scan the first 20 items to find the Header Row
  let headerRowIndex = -1;
  let colMap = { op: 0, analyst: 2, defectStart: 5 }; // Defaults

  // Keywords we look for to identify columns
  const KEYWORDS = {
      op: ['OP', 'ORDEM'],
      analyst: ['ANALISTA', 'OPERADOR', 'RESPONSAVEL'],
      defectStart: ['MANCHAS', 'DEFEITO', 'SUJOS', 'FALHA'] // First defect column usually has one of these
  };

  // Helper to normalize string for comparison
  const norm = (str) => String(str).toUpperCase().trim();

  for (let i = 0; i < Math.min(items.length, 20); i++) {
      const rowObj = items[i].json;
      const values = Object.values(rowObj).map(v => norm(v));

      // Check if this row has 'ANALISTA' or 'OP'
      const hasAnalyst = values.some(v => KEYWORDS.analyst.some(k => v.includes(k)));
      const hasOP = values.some(v => KEYWORDS.op.some(k => v === k)); // Exact match for OP usually

      if (hasAnalyst || hasOP) {
          headerRowIndex = i;

          // Map columns based on this row's content
          values.forEach((val, idx) => {
              if (KEYWORDS.op.some(k => val === k)) colMap.op = idx;
              if (KEYWORDS.analyst.some(k => val.includes(k))) colMap.analyst = idx;
              // Defect start is tricky, usually the first column after metadata that looks like a defect name
              if (colMap.defectStart === 5 && KEYWORDS.defectStart.some(k => val.includes(k))) {
                  colMap.defectStart = idx;
              }
          });
          break;
      }
  }

  // Process Data Rows
  for (let i = 0; i < items.length; i++) {
    if (i <= headerRowIndex) continue; // Skip header and pre-header rows

    const rowObj = items[i].json;
    const values = Object.values(rowObj);

    const opValue = values[colMap.op];
    if (!opValue || isNaN(Number(opValue)) || Number(opValue) < 1000) continue;

    const opName = values[colMap.analyst] ? String(values[colMap.analyst]).toUpperCase() : 'DESCONHECIDO'; 
    const machineName = 'ACABAMENTO'; 
    const dateStr = 'DEZEMBRO/2025'; 

    if (!operators[opName]) operators[opName] = { name: opName, totalIssues: 0, byMachine: {} };
    if (!machines[machineName]) machines[machineName] = { name: machineName, totalIssues: 0 };
    if (!timeline[dateStr]) timeline[dateStr] = 0;

    let rowIssues = 0;
    const keys = Object.keys(rowObj);

    // Scan for defects starting from detected index up to End-1
    for (let j = colMap.defectStart; j < values.length - 1; j++) {
        const val = Number(values[j]);
        if (!isNaN(val) && val > 0) {
            // Try to find the defect name from the Header Row if we found one
            let defectLabel = `Defeito ${j}`;
            if (headerRowIndex !== -1) {
                 const headerRowValues = Object.values(items[headerRowIndex].json);
                 if (headerRowValues[j]) defectLabel = String(headerRowValues[j]).trim();
            } else if (keys[j]) {
                 defectLabel = keys[j];
            }

            if(defectLabel.includes('Column') || defectLabel.includes('Empty')) defectLabel = `Tipo ${j}`;

            rowIssues += val;
            operators[opName].totalIssues += val;
            if (!defectsCount[defectLabel]) defectsCount[defectLabel] = 0;
            defectsCount[defectLabel] += val;
        }
    }

    timeline[dateStr] += rowIssues;
    totalIssuesOverall += rowIssues;
  }

  const calculateEfficiency = (issues, total) => Math.max(0, 100 - (issues * 0.5)); 

  const operatorsArray = Object.values(operators).map(op => ({
    ...op,
    efficiency: calculateEfficiency(op.totalIssues, items.length)
  })).sort((a,b) => b.totalIssues - a.totalIssues);

  const defectDistArray = Object.keys(defectsCount).map(k => ({ name: k, value: defectsCount[k] })).sort((a,b) => b.value - a.value).slice(0, 10);
  const timelineArray = Object.keys(timeline).map(k => ({ name: k, issues: timeline[k] }));

  return [{
    json: {
      timestamp: new Date().toISOString(),
      totalProcessed: items.length,
      overallEfficiency: calculateEfficiency(totalIssuesOverall, items.length),
      operators: operatorsArray,
      machines: Object.values(machines),
      processTypeBreakdown: {},
      defectDistribution: defectDistArray,
      timelineData: timelineArray,
      debug: `Dynamic Mode: Header Found at Row ${headerRowIndex}, Defects Start at Col ${colMap.defectStart}`
    }
  }];
} catch (error) {
  return [{ json: { error: 'Script Error: ' + error.message } }];
}
